#include "AForm.hpp"
#include "ShrubberyCreationForm.hpp"
#include "Bureaucrat.hpp"

ShrubberyCreationForm::ShrubberyCreationForm( std::string target ) : AForm("ShrubberyCreationForm", 145, 137), _target(target), _signed(0){
    
    std::cout << "Constructor ShrubberyCreationForm called " << std::endl;
}

ShrubberyCreationForm::ShrubberyCreationForm( ShrubberyCreationForm const & src ) : AForm(src) {

    std::cout << "Copy Constructor ShrubberyCreationForm called " << std::endl;
    *this = src;   
}

ShrubberyCreationForm::~ShrubberyCreationForm( void ){
    
    std::cout << "Destructor ShrubberyCreationForm called " << std::endl;
}

ShrubberyCreationForm & ShrubberyCreationForm::operator=( ShrubberyCreationForm const & other ){
    
    if (this != &other){
        AForm::operator=(other);
        this->_signed = other._signed;
        this->_target = other._target;
    }
    std::cout << "Assignment Operator ShrubberyCreationForm called " << std::endl;
    
    return *this;
}

std::string ShrubberyCreationForm::getTarget( void ) const{

    return this->_target;
}

const char* ShrubberyCreationForm::GradeToSignException::what() const throw(){
    
    return ("Invalid Grade to sign");
}

const char* ShrubberyCreationForm::GradeToExecuteException::what() const throw(){
    
    return ("Invalid Grade to execute");
}
    
void    ShrubberyCreationForm::createFiles( void ) const{

    std::string	buf = 
    
                        "                            .-:.: . .: : .-.-- :         .                             \n"
                        "                            --=..:-:----  : .:.:-:.  . .-:: ..                         \n"
                        "                           .+=- +=+=-=+.. *.:==-= .:.:=+*+==...                        \n"
                        "                          -- -====:  : +..:-:-:-=+=.::-.+=++*=:+==                     \n"
                        "                       :=-:=#=-=++++*   :+ -++*#-**+*+==#+===  +:      .               \n"
                        "                   .   = .* +:+==+:*.-+  -=++****+- -+:.+ *=+++.=.    =-               \n"
                        "              :-+.=:= ..  :.=+=*** =%%++#% *%++#*:===-**-*  ::-+.:=+.-  . ..           \n"
                        "            :+:-=--= :::=-.+:*++++*++.#-%##.+=:+++:==**+:==::==+++-:=+=  ::            \n"
                        "            :*-==:****++*:=+=+=-  :--*+#++=+**==++.*=#+ =-.     *. =**+*+-:. .:        \n"
                        "           :=* .=+=* *+*#+#==+*++*=*+=%*+-:*#+=+*++*=%==.-*-++-#*=-==#**= +- -         \n"
                        "          .++++==*+=+    :***#*+*=*+:*#%%%#: #+**+:+#%*++- +*+*#**+=-=+=+:-:-:-        \n"
                        "         +:=+ ++=+**#+#*  #++#*+*#*#++++#*#*%%**####*#+#+*+**.-= *  :=+=-*.=:-         \n"
                        "         +*- -++*=+ +*+* .:#+***#+#*=***+=#=**###++#*%%#---+=*+===+=:  +-==-: :        \n"
                        "        ==-=++=+-:++**++-==**#*###**=#*+**+***= ##*#+##*=  --+*+=-++----=:: -:.        \n"
                        "       =* # .*  .*  ++-=*#*#*#**##+ #%##=++*+*###-*=***#*+*+#*++**+*++=-=. -+          \n"
                        "         -.       .:-+:+== =**=**#*=%%%+* *+++==*###**##+*++-:*++**== -=:.             \n"
                        "                -  -+ ++===+*==*+*:*-#=+#**+*=*#:#%#*#*-#*##++*+*=:--.+-               \n"
                        "             -.* =+ --+=* +*-+*#=-:+*-** #+ .*# -%% *+*##*#%*  ==+==:.--.              \n"
                        "             : + +-.+...   +-.=#=- +:+*  -#%#  **#=*   .++++*+##-+     .               \n"
                        "               -    - =    --+=   =::*-   =%%%##-#      :+    . +=  =..-               \n"
                        "                .-       +  .      +:*#* = %#%+*-:=                                    \n"
                        "                          .      .+*#++*#%###%:*# +=                                   \n"
                        "                                 +.+=** -%%% -=%=*-+++-                                \n"
                        "                                . #+   :###*+ = =+=  -=:                               \n"
                        "                                        **+     -                                      \n"
                        "                                        ##=                                            \n"
                        "                                        #*#                                            \n"
                        "                             .. .:-  ..=##+-=: :-.                                     \n"
                        " . ..:=-::=-:-==:-=----+=+++**+===++++++++*+*+*#+=::--==-------::-::---:---:--::.....::\n";
    
                        
    std::string name = getTarget() +  "_shrubbery";
    std::ofstream ofs( name.c_str() );
    
	if (ofs.is_open()){
		ofs << buf;
	}
	else {
		std::cerr << "Error: file doesn't open" << std::endl;
		return;
	}
	ofs.close();
}

void    ShrubberyCreationForm::execute( Bureaucrat const & executor ) const{
    
    if ( getSigned() == 0 )
        throw AForm::NotSignedException();
    if ( executor.getGrade() <= getGradeToExecute() )
        createFiles();
    else
        throw AForm::GradeTooLowException();
}







